def normalize(res, round_to=2):
        # we round the result to 2 decimal places
        res = custom_round(res, round_to)
        res = str(res)
        if "." in res:
            while res[-1] == "0":
                res = res[:-1]
            res = res.strip(".")

        # scientific notation
        if "e" in res:
            res = scito_decimal(res)

        return res

